mapper.select:
SELECT bill_type AS tabFlag, count(id) AS count FROM stocktaking_profit_loss spl WHERE is_deleted=FALSE
${permissionSql}
GROUP BY bill_type

SELECT spl.id, spl.id AS mainId, spl.code, spl.source_id AS sourceId, spl.source_code AS sourceCode, spl.bill_type AS billType, spl.create_time AS createTime, spl.create_user_name AS createUserName, spl.approve_time AS approveTime, spl.approve_user_name AS approveUserName, spl.approve_status AS approveStatus, spld.id as detailId, spld.sku_no AS skuNo, spld.sku_id AS skuId, spld.warehouse_id AS warehouseId, spld.warehouse_location AS warehouseLocation, spld.qty, spld.usable_qty AS usableQty, spld.frozen_qty AS frozenQty, spld.diff_qty AS diffQty, w.name AS warehouseName, wl.name as warehouseLocationName FROM stocktaking_profit_loss spl INNER JOIN stocktaking_profit_loss_detail spld ON spl.id=spld.main_id AND spld.is_deleted=FALSE LEFT JOIN warehouse w ON spld.warehouse_id=w.id AND w.is_deleted=FALSE left join warehouse_location wl on spld.warehouse_location = wl.code and spld.warehouse_id = wl.warehouse_id and wl.is_deleted = false WHERE ${params.sqlMap.default} and spl.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spl.id DESC,spld.id DESC

SELECT spl.id, spl.code, spl.source_id AS sourceId, spl.source_code AS sourceCode, spl.bill_type AS billType, spl.create_time AS createTime, spl.create_user_name AS createUserName, spl.approve_time AS approveTime, spl.approve_status AS approveStatus, spl.approve_user_name AS approveUserName, spld.sku_no AS skuNo, spld.sku_id AS skuId, spld.warehouse_id AS warehouseId, spld.warehouse_location AS warehouseLocation, spld.qty, spld.usable_qty AS usableQty, spld.frozen_qty AS frozenQty, spld.diff_qty AS diffQty, w.name AS warehouseName, wl.name as warehouseLocationName FROM stocktaking_profit_loss spl INNER JOIN stocktaking_profit_loss_detail spld ON spl.id=spld.main_id AND spld.is_deleted=FALSE LEFT JOIN warehouse w ON spld.warehouse_id=w.id AND w.is_deleted=FALSE left join warehouse_location wl on spld.warehouse_location = wl.code and spld.warehouse_id = wl.warehouse_id and wl.is_deleted = false WHERE ${params.sqlMap.default} and spl.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spl.id DESC,spld.id DESC

SELECT spl.id AS sourceId, spl.code AS sourceCode, spl.bill_date AS billDate, spld.id AS sourceDetailId, spld.diff_qty AS qty, spld.sku_id, spld.sku_no, spld.warehouse_id, spld.warehouse_location FROM stocktaking_profit_loss_detail spld LEFT JOIN stocktaking_profit_loss spl ON spld.main_id=spl.id AND spl.is_deleted=FALSE WHERE spld.is_deleted=FALSE
AND spl.id IN
#{id}

SELECT warehouseOrgId, billDate, skuId, warehouseId, warehouseLocation, code FROM ( SELECT wh.org_id AS warehouseOrgId, spld.warehouse_id AS warehouseId, spld.warehouse_location AS warehouseLocation, spl.bill_date AS billDate, spld.sku_id AS skuId, spl.code, ROW_NUMBER ( ) OVER ( PARTITION BY wh.org_id, spld.warehouse_id, spld.warehouse_location, spld.sku_id ORDER BY spl.bill_date DESC ) AS row_num FROM stocktaking_profit_loss_detail spld LEFT JOIN stocktaking_profit_loss spl ON spld.main_id = spl. ID LEFT JOIN warehouse wh ON spld.warehouse_id = wh.ID WHERE spld.is_deleted = FALSE AND spl.is_deleted = FALSE AND spl.approve_status = 'approve'
AND spld.warehouse_id IN
#{id}
AND wh.org_id IN
#{id}
AND spld.sku_id IN
#{id}
) subquery WHERE row_num = 1

SELECT
    spl.code as maxCode
FROM stocktaking_profit_loss_detail spld
LEFT JOIN stocktaking_profit_loss spl
ON spld.main_id=spl.id
WHERE spld.is_deleted=FALSE AND spl.is_deleted=FALSE
  AND spl.approve_status = 'approve'

    AND spl.bill_date = #{billDate}


    AND spld.warehouse_id = #{warehouseId}


    AND spld.sku_id = #{skuId}
